const tweets = Array.isArray($json.tweets) ? $json.tweets : [];
const configuredUsername = $env.XQUIK_USERNAME.replace(/^@/, '');
const fetchedAt = new Date().toISOString();
const hasNextPage = $json.has_next_page === true;
const nextCursor = typeof $json.next_cursor === 'string' ? $json.next_cursor : '';
const count = (value) => {
  const parsed = Number(value ?? 0);
  return Number.isFinite(parsed) ? parsed : 0;
};

if (tweets.length === 0) {
  return [{
    json: {
      status: 'no_results',
      username: configuredUsername,
      hasNextPage,
      nextCursor,
      fetchedAt,
    },
  }];
}

return tweets.map((tweet) => {
  const username = tweet.author?.username ?? configuredUsername;
  const id = tweet.id ?? '';
  return {
    json: {
      status: 'ok',
      id,
      username,
      text: tweet.text ?? '',
      createdAt: tweet.createdAt ?? '',
      engagement: count(tweet.likeCount) + count(tweet.retweetCount) + count(tweet.replyCount) + count(tweet.quoteCount),
      url: tweet.url ?? (id ? `https://x.com/${username}/status/${id}` : ''),
      hasNextPage,
      nextCursor,
      fetchedAt,
    },
  };
});
